refsection.programlisting:
a = ["A"; "B"; "C"];
b = hours([1;3;5]);
c = rand(3,1);
t = table(a, b, c, "VariableNames", ["string", "hours", "double"]);
parquetWrite(fullfile(TMPDIR, "data.parquet"), t)
parquetRead(fullfile(TMPDIR, "data.parquet"))

// t = [3x3 table]
// 
//    string    hours      double  
//    ______   ________   _________
//                                 
//    A        01:00:00   0.2113249
//    B        03:00:00   0.7560439
//    C        05:00:00   0.0002211

a = ["A"; "B"; "C"];
b = hours([1;3;5]);
c = rand(3,1);
ts = timeseries(b, a, c, "VariableNames", ["hours", "string", "double"]);
parquetWrite(fullfile(TMPDIR, "data.parquet"), ts)
ts2 = parquetRead(fullfile(TMPDIR, "data.parquet"), "OutputType", "timeseries")

// ts2 = [3x2 timeseries]
//
//    hours     string    double  
//   ________   ______   _________
//                                
//   01:00:00   A        0.2113249
//   03:00:00   B        0.7560439
//   05:00:00   C        0.0002211
